// One chunk per heading-led block, which for the one-page synthetic document
// is one chunk.  Chunking a four-paragraph page into thirty slices would
// demo a tuning knob rather than the pipeline.
const md = (($json.document || {}).md_content || '').trim();
if (!md) {
  throw new Error('Docling returned no markdown: ' + JSON.stringify($json).slice(0, 300));
}
return [{ json: { source: 'synthetic.pdf', content: md } }];

// Same literal-building step as W1, for the same reason: the vector travels
// as a bound parameter, so nothing about an embedding can change the shape of
// the INSERT.
const row = ($json.data || [])[0];
if (!row || !Array.isArray(row.embedding)) {
  throw new Error('no embedding in the LiteLLM response: ' + JSON.stringify($json).slice(0, 200));
}
if (row.embedding.length !== 768) {
  throw new Error('expected 768 dimensions from local-embed, got ' + row.embedding.length);
}
return [{
  json: {
    source: $('Chunk the markdown').first().json.source,
    content: $('Chunk the markdown').first().json.content,
    vec: '[' + row.embedding.join(',') + ']',
  },
}];
